edit(j,1,title='Evaluate Featured Offer competitiveness without automatic undercutting',summary='Assess price, availability, delivery and seller performance together when competing on a shared ASIN.',use_when='Managing pricing and fulfillment for a legitimate reseller offer on an existing Amazon ASIN.',steps=['Check whether the offer is eligible for the Featured Offer in the relevant marketplace.','Compare total customer price, delivery promise, stock availability and seller performance.','Set a minimum contribution floor before changing prices; the lowest price alone does not guarantee selection.','Monitor offer share and profitable units sold, rather than following the source\'s unverified 90% lowest-price rule.','Configure repricing limits if automated and review results as competitors or stock levels change.'],caveats=['Amazon determines the Featured Offer; no fixed one-cent reduction guarantees it.'])
edit(j,4,summary='Separate seller feedback from product reviews and resolve order problems without linking remedies to ratings.',steps=['Review seller feedback and product reviews in their appropriate tools.','Where feedback appears eligible for removal, use the current official process and confirm the applicable deadline and criteria.','Resolve legitimate delivery or product problems through approved support channels.','Never offer a refund or other benefit to induce a review change or removal, even indirectly.','Record packing, listing or fulfillment causes and correct recurring issues; reimbursement and removal outcomes depend on current terms and evidence.'],caveats=['The source\'s 30-day deadline and instant removal example are not represented as current universal rules.'])
